function Counter() {
  const [count, setCount] = useState(0);

  console.log("render", count);

  return <button onClick={() => setCount(count + 1)}>{count}</button>;
}

function LikeButton() {
  const [likes, setLikes] = useState(0);

  function addThree() {
    setLikes((current) => current + 1);
    setLikes((current) => current + 1);
    setLikes((current) => current + 1);
  }

  return <button onClick={addThree}>{likes} likes</button>;
}

function UndoExample() {
  const [likes, setLikes] = useState(0);

  function reset() {
    setLikes(0);
    console.log(likes);
  }

  return <button onClick={reset}>Reset</button>;
}

function Tabs({ activeItem }) {
  return <Panel item={activeItem} />;
}

function Panel({ item }) {
  const [isOpen, setIsOpen] = useState(true);
  return <button onClick={() => setIsOpen((open) => !open)}>{isOpen ? item.title : "Closed"}</button>;
}

function App({ selectedId }) {
  return selectedId ? <Details key={selectedId} id={selectedId} /> : null;
}

function Details({ id }) {
  const [note, setNote] = useState("");
  return <textarea value={note} onChange={(event) => setNote(event.target.value)} />;
}

function Greeting({ name }) {
  return <h1>Hello, {name}</h1>;
}

